MD9 & 8923 +Vip3wZcgcreate -g cpu:mygroup44 & 55 $ echo 'Yd$@C#M05MD9&8923+Vip3wZ!33*44&55' Yd $@ C#M05MD9 & 8923 +Vip3wZ!33*44 & 55 $ echo 'Yd$@C#M05MD9&8923+Vip3wZ!33*44&55' | awk '{gsub(/[^0-9]/,"");print $0}' 05989233334455 $ echo 'Yd$@C#M05MD9&8923+Vip3wZ!33*44&55' | awk -F '[^0-9]' '{for(i=1;i<=NF;i++){printf "%s", $i}}' 05989233334455 $ echo 'Yd$@C#M05MD9&8923+Vip3wZ!33*44&55' | awk -F "" '{for(i=1;i<=NF;i++){if($i ~ /[[:digit:]]/){str=$i;str1=(str1 str)}};print str1}' 05989233334455 $ echo 'Yd$@C#M05MD9&8923+Vip3wZ!33*44&55' | awk -F '' '{for(i=1;i<=NF;i++){if($i ~ /[[:digit:]]/){str=$i;str1=(str1 str)}};print str1}' # 注意，如果写成如下格式，则报错。 $ echo 'Yd$@C#M05MD9&8923+Vip3wZ!33*44&55' | awk -F '' '{for(i=1;i<=NF;i++){if($i ~ /[[:digit:]]/){str=$i;str1=(str1 str)}};print str1}' # 注意，如果写成如下格式，则输出原字符串。 $ echo 'Yd$@C#M05MD9&8923+Vip3wZ!33*44&55' | awk -F ' ' '{for(i=1;i<=NF;i++){if($i ~ /[[:digit:]]/){str=$i;str1=(str1 str)}};print str1}' 生成500个随机数，保存到文件random.txt中，格式为 100,20,61,98... ，取出其中最大整数和最小整数。 $ str = "" ; for (( i = 1 ; i< = 500 ; i++ )) ; do if [ $i -ne 500 ] ; then str += " $RANDOM ," ; else str += " $RANDOM " ; fi ; done ; echo " $str " > random.txt $ cat random.txt 11308 ,8764,2075,9411,...... $ awk -F, '{max=$1;min=$1;for(i=1;i<=NF;i++){if($i>max){max=$i}else{if($i<min){min=$i}}}}END{print "The max:" max, "The min:" min}' random.txt The max:32696 The min:20 监控某个IP并发连接超过200时，调用防火墙命令封掉该IP，每5分钟监控一次。防火墙命令 iptables -A INPUT -s IP -j REJECT 。 ss -nt | awk -F " +|:" 'NR!=1{ip[$(NF-2)]++}END{for(i in ip){if(ip[i]>200){system("iptables -A INPUT -s " i " -j REJECT;")}}}' 将下面内容中FQDN取出，并根据其进行计数，从高到低排序。 $ cat > fqdn.txt << EOF http://mail.edu.com/index.html http://www.edu.com/test.html http://study.edu.com/index.html http://blog.edu.com/index.html http://www.edu.com/images/logo.jpg http://blog.edu.com/20080102.html EOF $ awk -F "/" '{url[$3]++}END{for(i in url){print url[i], i}}' fqdn.txt | sort -nr 2 www.edu.com 2 blog.edu.com 1 study.edu.com 1 mail.edu.com 将以下⽂本以inode为标记，对inode相同的counts进⾏累加，并且统计出同一inode中，beginnumber的最小值和endnumber的最大值。 inode | beginnumber | endnumber | counts | 106 | 3363120000 | 3363129999 | 10000 | 106 | 3368560000 | 3368579999 | 20000 | 310 | 3337000000 | 3337000100 | 101 | 310 | 3342950000 | 3342959999 | 10000 | 310 | 3362120960 | 3362120961 | 2 | 311 | 3313460102 | 3313469999 | 9898 | 311 | 3313470000 | 3313499999 | 30000 | 311 | 3362120962 | 3362120963 | 2 | 输出的结果格式为： 310 | 3337000000 | 3362120961 | 10103 | 311 | 3313460102 | 3362120963 | 39900 | 106 | 3363120000 | 3368579999 | 30000 | $ cat > inode.text << EOF inode|beginnumber|endnumber|counts| 106|3363120000|3363129999|10000| 106|3368560000|3368579999|20000| 310|3337000000|3337000100|101| 310|3342950000|3342959999|10000| 310|3362120960|3362120961|2| 311|3313460102|3313469999|9898| 311|3313470000|3313499999|30000| 311|3362120962|3362120963|2| EOF $ awk -F '|' -v OFS = '|' '/^[0-9]/{inode[$1]++; if(!bn[$1]){bn[$1]=$2}else if(bn[$1]>$2) {bn[$1]=$2}; if(en[$1]<$3)en[$1]=$3;cnt[$1]+=$(NF-1)} END{for(i in inode)print i,bn[i],en[i],cnt[i]}' inode.text 106 | 3363120000 | 3368579999 | 30000 310 | 3337000000 | 3362120961 | 10103 311 | 3313460102 | 3362120963 | 39900
